import { forwardRef, useImperativeHandle, useRef, type CSSProperties, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface TypedSplitWipeProps {
  prefix: string;
  anchor: string;
  suffix: string;
  typeFrames?: number;
  exitAt?: number;
  exitFrames?: number;
  wordStagger?: number;
  anchorShift?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};
const wipeEasing = Easing.inOut(Easing.quad);

function TypedSplitWipeBase({
  prefix,
  anchor,
  suffix,
  typeFrames = 30,
  exitAt = 50,
  exitFrames = 20,
  wordStagger = 4,
  anchorShift = -72,
  fontSize = 42,
  color = "#e8e8e8",
  fontWeight = 400,
  speed = 1,
  className,
}: TypedSplitWipeProps) {
  const frame = useCurrentFrame() * speed;
  const fullText = [prefix, anchor, suffix].filter(Boolean).join(" ");
  const safeTypeFrames = Math.max(typeFrames, 0.001);
  const safeExitFrames = Math.max(exitFrames, 0.001);
  const typedLength = interpolate(
    frame,
    [0, safeTypeFrames],
    [0, fullText.length],
    clamp,
  );
  const visibleLength = Math.min(
    fullText.length,
    Math.max(frame >= 0 ? 1 : 0, Math.floor(typedLength) + 1),
  );
  const typedText = fullText.slice(0, visibleLength);
  const suffixWords = suffix.trim().split(/\s+/).filter(Boolean);

  const textStyle: CSSProperties = {
    color,
    fontFamily:
      "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
    fontSize,
    fontWeight,
    letterSpacing: "-0.03em",
    lineHeight: 1,
    whiteSpace: "pre",
  };

  const prefixExit = interpolate(
    frame,
    [exitAt, exitAt + safeExitFrames],
    [0, 1],
    { ...clamp, easing: wipeEasing },
  );
  const anchorExitStart = exitAt + Math.max(exitFrames - 6, 0);
  const anchorExit = interpolate(
    frame,
    [anchorExitStart, anchorExitStart + 6],
    [0, 1],
    { ...clamp, easing: wipeEasing },
  );

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      {frame < exitAt ? (
        <span className={className} style={textStyle}>
          {typedText}
        </span>
      ) : (
        <span
          className={className}
          style={{
            ...textStyle,
            display: "inline-flex",
            alignItems: "baseline",
            gap: "0.25em",
          }}
        >
          {prefix && (
            <span
              style={{
                display: "inline-block",
                clipPath: `inset(0 ${prefixExit * 100}% 0 0)`,
              }}
            >
              {prefix}
            </span>
          )}

          {anchor && (
            <span
              style={{
                display: "inline-block",
                clipPath: `inset(0 ${anchorExit * 50}% 0 ${anchorExit * 50}%)`,
                transform: `translateX(${anchorShift * prefixExit}px)`,
              }}
            >
              {anchor}
            </span>
          )}

          {suffixWords.map((word, index) => {
            const wordExitStart = exitAt + 2 + index * wordStagger;
            const wordExit = interpolate(
              frame,
              [wordExitStart, wordExitStart + safeExitFrames * 0.65],
              [0, 1],
              { ...clamp, easing: wipeEasing },
            );

            return (
              <span
                key={`${word}-${index}`}
                style={{
                  display: "inline-block",
                  clipPath: `inset(0 0 0 ${wordExit * 100}%)`,
                }}
              >
                {word}
              </span>
            );
          })}
        </span>
      )}
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  prefix: {
    type: "text-content",
    default: "Introducing",
    description: "Leading text",
  },
  anchor: {
    type: "text-content",
    default: "X",
    description: "Persistent anchor",
  },
  suffix: {
    type: "text-content",
    default: "Ads MCP",
    description: "Staggered trailing words",
  },
  typeFrames: {
    type: "number",
    min: 6,
    max: 60,
    step: 1,
    default: 30,
    description: "Typing frames",
    hiddenFromList: false,
  },
  exitAt: {
    type: "number",
    min: 20,
    max: 90,
    step: 1,
    default: 50,
    description: "Exit start frame",
    hiddenFromList: false,
  },
  exitFrames: {
    type: "number",
    min: 6,
    max: 40,
    step: 1,
    default: 20,
    description: "Exit duration",
    hiddenFromList: false,
  },
  wordStagger: {
    type: "number",
    min: 0,
    max: 12,
    step: 1,
    default: 4,
    description: "Suffix word stagger",
    hiddenFromList: false,
  },
  anchorShift: {
    type: "number",
    min: -200,
    max: 0,
    step: 2,
    default: -72,
    description: "Anchor exit shift",
    hiddenFromList: false,
  },
  fontSize: {
    type: "number",
    min: 18,
    max: 120,
    step: 1,
    default: 42,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#e8e8e8",
    description: "Text color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["prefix","anchor","suffix","typeFrames","exitAt","exitFrames","wordStagger","anchorShift","fontSize","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  prefix: "Introducing",
  anchor: "X",
  suffix: "Ads MCP",
  typeFrames: 30,
  exitAt: 50,
  exitFrames: 20,
  wordStagger: 4,
  anchorShift: -72,
  fontSize: 42,
  color: "#e8e8e8",
  fontWeight: "400",
  speed: 1,
};

type TypedSplitWipeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypedSplitWipeBase>;

const TypedSplitWipeInner = forwardRef<
  HTMLDivElement,
  TypedSplitWipeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypedSplitWipe>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypedSplitWipeBase
          {...(componentProps as unknown as ComponentProps<typeof TypedSplitWipeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypedSplitWipe = Interactive.withSchema({
  Component: TypedSplitWipeInner,
  componentName: "<TypedSplitWipe>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
